async function previewBulkFile(file){
 try{
  const rawRows=(/\.xlsx$/i.test(file.name)&&typeof window.geReadTabularFileV223==='function')?await window.geReadTabularFileV223(file):parseCSV((await file.text()).replace(/^﻿/,''));const csv=Array.isArray(rawRows)?rawRows.slice():[],head=csv.shift()?.map(x=>String(x||'').trim())||[],source=collectionFor();
  if(source==='lounges'){document.querySelector('#planningDialog [data-close]')?.click();return window.openBulkImportV223?.('lounge')}
  if(!head.some(k=>fieldsFor(source).includes(k)&&k!=='id'))throw Error('CSV headers do not match this page template.');
  const incoming=csv.map((line,i)=>({line:i+2,row:Object.fromEntries(head.map((key,j)=>[key,line[j]||'']))})),allowed=new Set(categories(d).map(x=>x.id));
  const reviewed=incoming.map(x=>{const reasons=[];if(!String(x.row.name||x.row.product||x.row.title||x.row.provider||'').trim())reasons.push('name');const st=String(x.row.stationCode||x.row.station||x.row.airport||x.row.stations||'').trim();if(!st)reasons.push('station');if(x.row.planningCategoryId&&!allowed.has(x.row.planningCategoryId))reasons.push('category');return {...x,reasons}});
  const valid=reviewed.filter(x=>!x.reasons.length),failed=reviewed.filter(x=>x.reasons.length);
  modal('Confirm Bulk Upload',`<div class="planning-upload-summary"><div><b>${incoming.length}</b><span>Total rows</span></div><div class="success"><b>${valid.length}</b><span>Ready</span></div><div class="danger"><b>${failed.length}</b><span>Failed validation</span></div></div><div class="ge-table-wrap"><table><thead><tr><th>Row</th><th>Name</th><th>Station</th><th>Result</th></tr></thead><tbody>${reviewed.slice(0,40).map(x=>`<tr><td>${x.line}</td><td>${E(x.row.name||x.row.product||x.row.title||x.row.provider||'—')}</td><td>${E(x.row.stationCode||x.row.station||x.row.airport||x.row.stations||'—')}</td><td>${x.reasons.length?`<span class="planning-import-bad">Check ${E(x.reasons.join(', '))}</span>`:'<span class="planning-import-ok">Ready</span>'}</td></tr>`).join('')}</tbody></table></div>`,valid.length?async()=>commitBulkRows(valid,source):undefined);
 }catch(e){modal('Bulk Upload',`<div class="planning-import-error">${E(e.message||String(e))}</div>`)}
}
async function commitBulkRows(incoming,source){
 const staged=arr(state[source]).map(row=>({...row})),stagedIds=new Set(staged.map(row=>String(row.id)));
 for(const x of incoming){const id=x.row.id||globalThis.crypto?.randomUUID?.()||String(Date.now())+'-'+x.line,item={...x.row,id,planningCategoryId:x.row.planningCategoryId||selected||''};if(source==='groundHandlers'&&x.row.stations!==undefined)item.stations=String(x.row.stations||'').split(/[;,|]/).map(v=>v.trim().toUpperCase()).filter(Boolean);if(stagedIds.has(String(id))){const old=staged.find(v=>String(v.id)===String(id));Object.assign(old,item)}else{staged.push(item);stagedIds.add(String(id))}}
 state[source]=staged;auditPlanning('Import',`${source}: ${incoming.length} rows`);GEStore.save(state);await GEStore.flush();document.querySelector('#planningDialog [data-close]')?.click();renderDomain();window.geStorageNoticeV223?.('Import Complete',`${incoming.length} records imported successfully.`,'success');
}
async function importCSV(file){try{const csv=parseCSV((await file.text()).replace(/^\ufeff/,'')),head=csv.shift()?.map(x=>x.trim())||[];const source=collectionFor();if(source==='lounges')throw Error('Use the upload feature on the Lounge/Tenant page.');if(!head.some(k=>fieldsFor(source).includes(k)&&k!=='id'))throw Error('CSV headers do not match this page template.'),incoming=csv.map((line,i)=>({line:i+2,row:Object.fromEntries(head.map((key,j)=>[key,line[j]||'']))}));const existing=new Set(arr(state[source]).map(x=>String(x.id))),categoriesAllowed=new Set(categories(d).map(x=>x.id));const invalid=incoming.filter(x=>x.row.planningCategoryId&&!categoriesAllowed.has(x.row.planningCategoryId));if(invalid.length)throw Error('Unknown category on row '+invalid.map(x=>x.line).join(', '));modal('Confirm Upload',`<p>${incoming.length} rows found. Records must use a valid service category. Existing IDs update only the columns supplied in the file; other fields are preserved.</p><div class="ge-table-wrap"><table><thead><tr><th>Row</th><th>Name</th><th>Station</th><th>Category</th></tr></thead><tbody>${incoming.slice(0,30).map(x=>`<tr><td>${x.line}</td><td>${E(x.row.name)}</td><td>${E(x.row.stationCode)}</td><td>${E(x.row.planningCategoryId||'—')}</td></tr>`).join('')}</tbody></table></div>`,async()=>{const staged=arr(state[source]).map(row=>({...row}));const stagedIds=new Set(staged.map(row=>String(row.id)));for(const x of incoming){const id=x.row.id||globalThis.crypto?.randomUUID?.()||String(Date.now())+'-'+x.line;const item={...x.row,id,planningCategoryId:x.row.planningCategoryId||(selected==='UNASSIGNED'?'':selected)||''};if(x.row.pricePeriods){try{item.pricePeriods=JSON.parse(x.row.pricePeriods);if(!Array.isArray(item.pricePeriods))throw Error()}catch{throw Error('Price periods on row '+x.line+' must be a JSON array exported from Download Data.') }}if(source==='groundHandlers'&&x.row.stations!==undefined)item.stations=String(x.row.stations||'').split(/[;,|]/).map(v=>v.trim()).filter(Boolean);if(stagedIds.has(String(id))){const old=staged.find(v=>String(v.id)===String(id));Object.assign(old,item);continue}staged.push(item);stagedIds.add(String(id))}state[source]=staged;auditPlanning('Import',`${source}: ${incoming.length} rows`);GEStore.save(state);await GEStore.flush()})}catch(e){status('Unable to process upload: '+e.message)}}
function modal(title,content,save){
 document.getElementById('planningDialog')?.remove();
 const layer=document.createElement('div');layer.id='planningDialog';layer.className='planning-dialog-layer';
 layer.innerHTML=`<section class="planning-dialog planning-dialog-card" aria-modal="true" aria-labelledby="planningDialogTitle"><div class="planning-modal-header"><div><h2 id="planningDialogTitle">${E(title)}</h2><p>Manage service details and agreement information by station.</p></div><button type="button" class="ge-btn planning-modal-close" data-close aria-label="Close dialog">×</button></div><div class="planning-modal-content">${content}</div><p id="planningError" class="planning-error" role="alert" aria-live="polite"></p><div class="ge-id-actions"><button type="button" class="ge-btn" data-close>Cancel</button>${save?'<button type="button" class="ge-btn primary" data-save>Save</button>':''}</div></section>`;
 document.body.appendChild(layer);const close=()=>layer.remove();layer.querySelectorAll('[data-close]').forEach(b=>b.addEventListener('click',close));layer.addEventListener('click',e=>{if(e.target===layer)close()});const onKey=e=>{if(e.key==='Escape'){document.removeEventListener('keydown',onKey,true);close()}};document.addEventListener('keydown',onKey,true);
 layer.querySelector('[data-save]')?.addEventListener('click',async e=>{const btn=e.currentTarget;if(btn.disabled)return;const error=layer.querySelector('#planningError');error.textContent='';const required=layer.querySelector('.planning-canonical-agreement-form [required]:invalid');if(required){required.focus();error.textContent='Complete the required fields.';return}btn.disabled=true;try{await save(layer);close();renderDomain();status('Data saved successfully.')}catch(err){error.textContent=err?.message||'Unable to save record.';btn.disabled=false}});
 return layer;
}
